<style>

:root { --ink:#101a35; --muted:#69738a; --blue:#3158e7; --purple:#8057ce; --teal:#15a999; --cloud:#f5f7fb; --line:#e5eaf3; --white:#fff; --radius:22px; --shadow:0 22px 70px rgba(19,33,66,.075); --container:1192px; }
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:"DM Sans",system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:#fff;-webkit-font-smoothing:antialiased}button,input,textarea{font:inherit}button{cursor:pointer}a{color:inherit;text-decoration:none}img{display:block;max-width:100%}svg{width:20px;height:20px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}::selection{background:#dbe5ff} :focus-visible{outline:3px solid #6a84ef;outline-offset:3px}
.container{width:min(calc(100% - 48px),var(--container));margin-inline:auto}.eyebrow{font-size:11px;line-height:1.4;text-transform:uppercase;letter-spacing:.17em;color:var(--blue);font-weight:800}.section-head{margin-bottom:34px}.section-head h2,.split-heading h2{font-family:Manrope,sans-serif;font-size:clamp(28px,3.1vw,42px);line-height:1.19;letter-spacing:-.052em;margin:13px 0 13px;font-weight:800}.section-head p,.split-heading p{color:var(--muted);line-height:1.85;font-size:15px;margin:0;max-width:690px}.tag{display:inline-flex;align-items:center;gap:8px;border:1px solid #dbe3f8;border-radius:100px;padding:8px 12px;font-size:11px;font-weight:800;letter-spacing:.055em;background:#f6f8ff;color:#4056a2}.tag .dot{height:7px;width:7px;border-radius:100%;background:var(--teal);box-shadow:0 0 0 4px rgba(21,169,153,.12)}
.btn{border:0;display:inline-flex;align-items:center;justify-content:center;gap:11px;border-radius:11px;padding:14px 19px;font-weight:800;font-size:13px;transition:transform .2s,background .2s,box-shadow .2s;text-align:center;white-space:nowrap}.btn:hover{transform:translateY(-2px)}.btn svg{width:16px;height:16px}.btn-primary{background:var(--blue);color:white;box-shadow:0 8px 20px rgba(49,88,231,.18)}.btn-primary:hover{background:#234bdc;box-shadow:0 12px 24px rgba(49,88,231,.25)}.btn-outline{background:white;color:var(--ink);border:1px solid #d9e0ee}.btn-dark{background:var(--ink);color:white}.btn-white{background:white;color:var(--blue)}.link-arrow{display:inline-flex;gap:8px;align-items:center;color:var(--blue);font-size:13px;font-weight:800}.link-arrow svg{width:16px;height:16px}
header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.96);backdrop-filter:blur(16px);border-bottom:1px solid var(--line)}.topbar{height:31px;background:var(--ink);color:#cad4e9;font-size:10px;letter-spacing:.045em}.topbar .container{height:100%;display:flex;justify-content:space-between;align-items:center}.topbar strong{font-weight:600;color:white}.nav{height:78px;display:flex;align-items:center;justify-content:space-between;gap:20px}.logo{display:flex;align-items:baseline;gap:0;font:800 24px Manrope,sans-serif;letter-spacing:-.075em;white-space:nowrap;color:#172b70}.logo span{color:#8655db}.logo .brand-dot{height:9px;width:9px;border-radius:50%;background:var(--blue);margin:0 1px 1px 1px;display:inline-block;box-shadow:0 0 0 3px #e7edff}.nav-links{display:flex;gap:31px;align-items:center;margin-left:auto}.nav-links a{font-size:12px;color:#47536d;font-weight:800;transition:color .2s}.nav-links a:hover,.nav-links a.active{color:var(--blue)}.nav-actions{display:flex;align-items:center;gap:12px;margin-left:20px}.icon-button{border:0;background:transparent;border-radius:10px;display:grid;place-items:center;width:38px;height:38px;color:#505e77}.icon-button:hover{background:#f0f4fb}.nav-actions .btn{padding:11px 17px;font-size:12px}.nav-actions .login{font-size:12px;font-weight:800;color:#46536d}.mobile-menu-btn{display:none}.mobile-panel{display:none}
/* HERO */
.hero{background:radial-gradient(ellipse at 85% 18%,#e8edff 0,transparent 44%),linear-gradient(145deg,#f7f9fd,#fff 58%,#fafbff);border-bottom:1px solid #e9edf5;overflow:hidden;position:relative}.hero:after{content:"";position:absolute;inset:auto auto -190px -150px;width:470px;height:470px;background:radial-gradient(circle,rgba(128,87,206,.09),transparent 70%);pointer-events:none}.hero-grid{min-height:630px;display:grid;grid-template-columns:.94fr 1.06fr;align-items:center;gap:62px;padding-block:80px 88px;position:relative;z-index:1}.hero h1{font-family:Manrope,sans-serif;font-size:clamp(40px,4.5vw,64px);line-height:1.13;letter-spacing:-.065em;font-weight:800;margin:25px 0 23px;max-width:595px}.hero h1 .gradient{background:linear-gradient(105deg,#3158e7 4%,#8057ce 75%);-webkit-background-clip:text;background-clip:text;color:transparent}.hero-copy>p{color:#637087;line-height:1.88;font-size:16px;max-width:515px;margin:0 0 30px}.hero-actions{display:flex;flex-wrap:wrap;gap:12px}.hero-audiences{margin-top:39px;padding-top:24px;border-top:1px solid #e0e7f1;display:flex;align-items:center;gap:15px}.hero-audiences .avatar-stack{display:flex;align-items:center;margin-left:0}.avatar-stack i,.avatar-stack img{width:35px;height:35px;border-radius:50%;border:3px solid #fff;margin-left:-8px;box-shadow:0 3px 8px rgba(16,26,53,.12);flex:none;position:relative;transition:transform .2s ease,box-shadow .2s ease}.avatar-stack img{object-fit:cover;background:#edf1f8}.avatar-stack i{display:grid;place-items:center;font-weight:800;font-size:10.5px;font-style:normal;color:#fff;background:var(--blue);text-align:center;line-height:1}.avatar-stack>*:first-child{margin-left:0!important}.avatar-stack>*:hover{transform:translateY(-3px) scale(1.1);z-index:30!important;box-shadow:0 6px 14px rgba(16,26,53,.2)}.hero-audiences small{display:block;font-size:11px;color:#7a8598;margin-bottom:3px}.hero-audiences strong{font-size:12px;letter-spacing:-.01em;font-weight:800;color:var(--ink)}
.hero-visual{position:relative;min-height:440px;display:flex;align-items:center;justify-content:center}.hero-visual:before{content:"";position:absolute;border:1px solid #e3e8f8;border-radius:50%;width:560px;height:560px;right:-92px;top:-74px;box-shadow:0 0 0 48px rgba(224,232,255,.2),0 0 0 108px rgba(224,232,255,.16);pointer-events:none}.dashboard{position:relative;width:100%;max-width:565px;background:#fff;border:1px solid #e2e7f3;border-radius:22px;box-shadow:0 35px 90px rgba(28,48,97,.15);overflow:hidden;transform:rotate(-1.2deg)}.dash-top{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid #edf0f7}.dash-dots{display:flex;gap:5px}.dash-dots i{width:7px;height:7px;border-radius:50%;background:#d6dded}.dash-dots i:first-child{background:#f39b9b}.dash-dots i:nth-child(2){background:#f3d28a}.dash-dots i:nth-child(3){background:#a4e1c0}.dash-top small{font-size:10px;color:#8b96aa;font-weight:700}.dash-body{padding:23px 25px 25px;background:linear-gradient(#fff,#fafbff)}.dash-header{display:flex;justify-content:space-between;align-items:center;gap:10px}.dash-header h3{font:800 19px Manrope,sans-serif;letter-spacing:-.04em;margin:5px 0 3px}.dash-header p{font-size:11px;color:#909bb0;margin:0}.dash-badge{width:37px;height:37px;background:#ecf0ff;color:var(--blue);display:grid;place-items:center;border-radius:11px}.dash-main{display:grid;grid-template-columns:1.16fr .84fr;gap:13px;margin-top:19px}.dash-card{background:#fff;border:1px solid #e8edf7;border-radius:15px;padding:16px}.dash-card .micro{color:#8d98af;font-size:9px;letter-spacing:.08em;text-transform:uppercase;font-weight:800}.dash-card h4{font-size:14px;font-weight:800;letter-spacing:-.025em;margin:10px 0 13px}.progress-row{display:flex;justify-content:space-between;align-items:center;font-size:10px;color:#506079;font-weight:700;margin-top:17px}.progress-row:first-of-type{margin-top:0}.progress{height:6px;background:#ebeff9;border-radius:8px;margin-top:7px;overflow:hidden}.progress b{display:block;height:100%;background:linear-gradient(90deg,var(--blue),#8c6be3);border-radius:8px}.dash-activity{background:#eff3ff;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.orbit{width:92px;height:92px;border:9px solid #d5e0ff;border-right-color:var(--blue);border-top-color:#7b63db;border-radius:50%;display:grid;place-items:center;transform:rotate(-32deg);margin:4px auto}.orbit svg{transform:rotate(32deg);width:29px;height:29px;color:var(--blue)}.dash-activity strong{font-size:12px}.dash-activity span{font-size:9px;color:#7d8aa6;margin-top:4px}.dash-bottom{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:13px}.dash-mini{display:flex;align-items:center;gap:9px;background:#fff;border:1px solid #edf0f7;border-radius:11px;padding:11px 10px}.mini-ic{width:28px;height:28px;border-radius:8px;display:grid;place-items:center;background:#eaf0ff;color:var(--blue)}.mini-ic svg{width:15px;height:15px}.dash-mini:nth-child(2) .mini-ic{background:#edf9f4;color:#1d9c82}.dash-mini:nth-child(3) .mini-ic{background:#f3edff;color:#865cd0}.dash-mini strong{font-size:10px;display:block}.dash-mini small{font-size:9px;color:#8f98aa}.floating{position:absolute;z-index:2;box-shadow:0 16px 38px rgba(28,48,97,.14);background:rgba(255,255,255,.96);border:1px solid #ecedf6;border-radius:13px;padding:12px 14px;display:flex;align-items:center;gap:10px}.floating .float-icon{border-radius:10px;width:33px;height:33px;display:grid;place-items:center;background:#dff8ef;color:#168e78}.floating strong{font-size:11px;display:block}.floating small{font-size:9px;color:#7b869e}.float-one{right:-24px;top:10px;transform:rotate(3deg)}.float-two{left:-24px;bottom:17px;transform:rotate(-3deg)}.float-two .float-icon{background:#eeeaff;color:#7753d1}
/* BENEFITS */
.benefits{padding:88px 0 94px;background:#fff}.benefits .section-head{text-align:center}.benefits .section-head p{margin:auto}.benefit-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:13px;margin-top:44px}.benefit-card{padding:26px 20px 25px;min-height:225px;background:#fff;border:1px solid var(--line);border-radius:17px;transition:transform .2s,box-shadow .2s,border-color .2s}.benefit-card:hover{transform:translateY(-5px);box-shadow:var(--shadow);border-color:#cfdcfb}.benefit-icon{height:46px;width:46px;border-radius:13px;display:grid;place-items:center;color:var(--blue);background:#eef2ff;margin-bottom:25px}.benefit-card:nth-child(2) .benefit-icon{background:#eef9f7;color:#159783}.benefit-card:nth-child(3) .benefit-icon{background:#f2edff;color:#835ed1}.benefit-card:nth-child(4) .benefit-icon{background:#fff6e5;color:#c98724}.benefit-card:nth-child(5) .benefit-icon{background:#e9f3ff;color:#2b7cc2}.benefit-card h3{font-size:14px;font-weight:800;line-height:1.5;margin:0 0 9px;letter-spacing:-.02em}.benefit-card p{font-size:12px;color:var(--muted);line-height:1.75;margin:0}
/* LEARNING MODES */
.learning{background:var(--cloud);padding:94px 0 103px}.learning .section-head{text-align:center;margin-bottom:54px}.learning .section-head p{margin-inline:auto}.format-labels{display:flex;justify-content:center;align-items:center;gap:8px;margin-top:20px;flex-wrap:wrap}.format-labels span{display:flex;gap:8px;align-items:center;padding:9px 15px;border:1px solid #e0e6f1;border-radius:50px;background:white;font-size:11px;font-weight:800;color:#5b6980}.format-labels svg{width:14px;height:14px;color:var(--blue)}.mode{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:78px;padding:43px 0}.mode+.mode{border-top:1px solid #dfe6f2;margin-top:41px;padding-top:80px}.mode-copy .line{height:3px;width:40px;background:var(--blue);margin:18px 0}.mode-copy .mode-number{color:var(--blue);font-weight:800;font-size:11px;letter-spacing:.13em}.mode-copy h3{font:800 clamp(28px,3vw,41px) Manrope,sans-serif;letter-spacing:-.05em;margin:9px 0 6px}.mode-copy h4{font-size:15px;line-height:1.6;color:var(--blue);margin:0 0 22px}.mode-copy>p{color:#66728a;font-size:14px;line-height:1.9;max-width:480px}.feature-list{list-style:none;margin:22px 0 30px;padding:0;display:grid;gap:14px}.feature-list li{display:flex;gap:11px;font-size:12px;line-height:1.7;color:#44516a;font-weight:600}.check-ic{margin-top:2px;display:grid;place-items:center;background:#e2f6ee;color:#14886f;width:18px;height:18px;flex:none;border-radius:50%}.check-ic svg{width:11px;height:11px;stroke-width:3}.mode-visual{min-height:385px;border-radius:24px;background:#e8eefc;border:1px solid #dfe7f5;display:flex;align-items:center;justify-content:center;padding:24px;position:relative;overflow:hidden}.mode-visual:before{content:"";position:absolute;border-radius:50%;width:250px;height:250px;background:rgba(64,91,227,.06);right:-95px;top:-120px}.mode-visual:after{content:"";position:absolute;border-radius:50%;width:160px;height:160px;background:rgba(157,97,206,.08);left:-65px;bottom:-65px}.class-window{position:relative;z-index:1;max-width:410px;width:100%;background:#fff;border:1px solid #e0e7f8;border-radius:16px;box-shadow:0 20px 40px rgba(42,66,111,.11);overflow:hidden}.window-bar{height:39px;border-bottom:1px solid #edf0f7;display:flex;gap:5px;align-items:center;padding:0 14px}.window-bar b{width:6px;height:6px;border-radius:50%;background:#cbd4e5}.class-content{padding:23px}.class-cover{min-height:156px;background:linear-gradient(130deg,#3158e7,#6d5ada);border-radius:11px;color:#fff;display:flex;justify-content:space-between;padding:20px;overflow:hidden;position:relative}.class-cover .cover-copy{position:relative;z-index:2}.class-cover small{display:block;opacity:.75;font-size:9px;letter-spacing:.15em;font-weight:800}.class-cover strong{display:block;margin-top:12px;font:800 19px Manrope,sans-serif;max-width:210px;line-height:1.35;letter-spacing:-.03em}.cover-circle{border:25px solid rgba(255,255,255,.16);width:185px;height:185px;border-radius:50%;position:absolute;right:-35px;top:-40px;display:grid;place-items:center}.cover-circle svg{width:70px;height:70px;color:white;stroke-width:1.1}.class-bottom{display:flex;gap:11px;align-items:center;margin-top:15px}.class-bottom .module-icon{width:40px;height:40px;display:grid;place-items:center;color:var(--blue);background:#ecf1ff;border-radius:10px}.class-bottom strong{font-size:12px}.class-bottom small{display:block;margin-top:3px;font-size:10px;color:#8995a9}.class-bottom .arrow{margin-left:auto;color:var(--blue)}.floating-tag{position:absolute;z-index:2;right:10px;bottom:29px;background:#fff;box-shadow:0 10px 30px rgba(30,49,98,.12);border-radius:10px;padding:11px 13px;display:flex;gap:8px;align-items:center;font-size:10px;font-weight:800;color:#46536d}.floating-tag svg{color:#138f7a}.mode-visual.boot{background:#e8f4f3}.boot .class-window{max-width:415px;transform:rotate(2deg)}.boot .class-cover{background:linear-gradient(125deg,#163b56,#147d83)}.boot .cover-circle{border-color:rgba(255,255,255,.13)}.boot .floating-tag{left:5px;right:auto;bottom:28px}
/* COMMUNITY */
.community{padding:94px 0 102px;background:#fff}.community-top{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:30px}.community-top .section-head{margin-bottom:0}.gallery-controls{display:flex;gap:8px}.round-control{border:1px solid #dce4f0;border-radius:50%;height:43px;width:43px;background:#fff;display:grid;place-items:center;color:var(--ink)}.round-control:hover{background:var(--ink);color:#fff}.gallery{display:flex;gap:17px;overflow-x:auto;scroll-behavior:smooth;scrollbar-width:none;padding:8px 4px 18px}.gallery::-webkit-scrollbar{display:none}.gallery-card{position:relative;flex:0 0 calc((100% - 51px)/4);height:247px;border-radius:16px;overflow:hidden;background:linear-gradient(130deg,#5d75af,#2a406f);isolation:isolate}.gallery-card img{width:100%;height:100%;object-fit:cover;object-position:center;transition:transform .4s}.gallery-card:hover img{transform:scale(1.06)}.gallery-card:after{content:"";position:absolute;inset:35% 0 0;background:linear-gradient(transparent,rgba(10,18,38,.78));z-index:1}.gallery-label{position:absolute;bottom:17px;left:17px;right:12px;z-index:2;color:white}.gallery-label small{opacity:.82;font-size:10px}.gallery-label strong{font-size:13px;line-height:1.4;display:block;margin-top:5px}.gallery-footer{margin-top:21px;display:flex;justify-content:space-between;align-items:center;gap:18px;font-size:12px;color:var(--muted)}.gallery-footer span{display:flex;align-items:center;gap:9px}.gallery-footer svg{color:var(--teal);width:16px;height:16px}
/* ABOUT */
.about{padding:94px 0;background:#101b37;color:white;position:relative;overflow:hidden}.about:before{position:absolute;content:"";height:440px;width:440px;border:1px solid rgba(255,255,255,.08);border-radius:50%;right:-200px;top:-220px;box-shadow:0 0 0 72px rgba(255,255,255,.025),0 0 0 155px rgba(255,255,255,.018)}.about .eyebrow{color:#99b0ff}.about .section-head{text-align:center;position:relative;margin-bottom:47px}.about .section-head h2{color:#fff}.about .section-head p{color:#bcc8df;margin-inline:auto}.about-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;position:relative}.about-card{background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.115);border-radius:16px;padding:26px 24px;min-height:220px}.about-card svg{width:26px;height:26px;color:#b7c7ff;margin-bottom:29px}.about-card h3{font-size:14px;margin:0 0 12px;font-weight:800}.about-card p{font-size:12px;line-height:1.85;color:#abbad3;margin:0}.about-strip{margin-top:22px;padding:23px 29px;display:flex;align-items:center;justify-content:space-between;gap:22px;border:1px solid rgba(255,255,255,.16);background:linear-gradient(105deg,rgba(66,91,216,.36),rgba(49,88,231,.08));border-radius:16px}.about-strip h3{margin:0 0 5px;font-size:18px;letter-spacing:-.035em}.about-strip p{margin:0;color:#ccd4e7;font-size:12px;line-height:1.7;max-width:730px}
/* CAMPUS */
.campuses{padding:100px 0 92px;background:#fff}.campuses .section-head{text-align:center;margin-bottom:66px}.campuses .section-head p{margin:auto}.campus{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:68px}.campus+.campus{margin-top:80px;padding-top:80px;border-top:1px solid #e9edf4}.campus.reverse .campus-photo{order:2}.campus.reverse .campus-info{order:1}.campus-photo{border-radius:20px;overflow:hidden;background:linear-gradient(140deg,#dce8f3,#9bc6c4);position:relative;box-shadow:0 14px 46px rgba(17,37,70,.10);height:345px}.campus-photo img{width:100%;height:100%;object-fit:cover;object-position:center;transition:transform .4s}.campus-photo:hover img{transform:scale(1.03)}.photo-label{position:absolute;left:18px;bottom:18px;border-radius:9px;padding:9px 12px;background:rgba(255,255,255,.9);font-size:10px;font-weight:800;backdrop-filter:blur(6px)}.campus-info h3{font:800 clamp(26px,2.5vw,34px) Manrope,sans-serif;letter-spacing:-.05em;margin:12px 0 16px}.campus-info>p{font-size:14px;color:var(--muted);line-height:1.85;margin:0 0 24px}.location{display:flex;align-items:center;gap:10px;margin:0 0 22px}.location .pin{height:38px;width:38px;display:grid;place-items:center;border-radius:11px;background:#ecf1ff;color:var(--blue)}.location small{font-size:10px;color:#8893a6;display:block}.location strong{font-size:12px}.amenities{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:25px}.amenities span{font-size:11px;font-weight:700;background:#f3f6fc;padding:8px 11px;border-radius:8px;color:#52617a}
/* INSTRUCTORS */
